def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])

    idx = 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(lines[idx + i])
        idx += n

        result = count_squares(matrix, n, m)
        results.append(str(result))

    return '\n'.join(results)

def count_squares(matrix, n, m):
    """Count valid squares (axis-aligned and diagonal) in the matrix."""
    count = 0

    # Get all positions of 1s for efficient lookup
    grid = [[0 for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '1':
                grid[i][j] = 1

    # For axis-aligned squares
    # Try all possible sizes and positions
    for side in range(2, min(n, m) + 1):
        for r1 in range(n - side + 1):
            for c1 in range(m - side + 1):
                if is_valid_axis_aligned_square(grid, n, m, r1, c1, side):
                    count += 1

    # For diagonal squares (diamond shape)
    # These have sides parallel to the matrix diagonals
    # A diagonal square of radius R has a bounding box of (2R+1) x (2R+1)
    for r in range(1, min(n, m) // 2 + 1):
        for cr in range(r, n - r):
            for cc in range(cc, m - r):
                # Actually we need to be more careful here
                pass

    # Let me use a cleaner approach for diagonal squares
    # For each possible center, try different radii

    for cr in range(1, n - 1):
        for cc in range(1, m - 1):
            # For diagonal squares, the "radius" is the Manhattan distance from center
            # The minimum valid diagonal square has radius 1 and side length 2 (in terms of grid cells)
            max_r = min(cr + n - cr - 1, cc + m - cc - 1) // 2
            for radius in range(1, max_r + 1):
                if is_valid_diagonal_square(grid, n, m, cr, cc, radius):
                    count += 1

    return count

def is_valid_axis_aligned_square(grid, n, m, r1, c1, side):
    """Check if there's a valid axis-aligned square frame from (r1, c1) with given side."""
    r2, c2 = r1 + side - 1, c1 + side - 1

    # Check all frame cells are 1
    # Top and bottom rows
    for j in range(c1, c2 + 1):
        if grid[r1][j] != 1 or grid[r2][j] != 1:
            return False

    # Left and right columns
    for i in range(r1, r2 + 1):
        if grid[i][c1] != 1 or grid[i][c2] != 1:
            return False

    # Collect all frame cells
    frame_cells = set()
    for j in range(c1, c2 + 1):
        frame_cells.add((r1, j))
        frame_cells.add((r2, j))
    for i in range(r1, r2 + 1):
        frame_cells.add((i, c1))
        frame_cells.add((i, c2))

    # Check isolation: no foreign 1s adjacent to frame
    # A cell can touch any 8 neighbors. Distance 0 (the frame itself) is OK.
    for r, c in frame_cells:
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if frame_cells == set() and (nr, nc) not in frame_cells:
                        # Don't want to check foreign cells that are part of THIS frame
                        # But since (nr, nc) is distance 1 from (r, c), it can't be in frame_cells if we properly constructed frame_cells
                        pass
                    elif grid[nr][nc] == 1 and (nr, nc) not in frame_cells:
                        return False

    return True

def is_valid_diagonal_square(grid, n, m, cr, cc, radius):
    """Check if there's a valid diagonal square centered at (cr, cc) with Manhattan radius."""
    frame_cells = set()

    # Cells with Manhattan distance = radius from center
    for i in range(max(0, cr - radius), min(n, cr + radius + 1)):
        # For each row, find columns where |i - cr| + |j - cc| = radius
        dist_row = abs(i - cr)
        if dist_row <= radius:
            dist_col = radius - dist_row
            if dist_col <= radius:
                # Two possible column positions (or one if distance is 0)
                if dist_col == 0:
                    frame_cells.add((i, cc))
                else:
                    if cc - dist_col >= 0:
                        frame_cells.add((i, cc - dist_col))
                    if cc + dist_col < m:
                        frame_cells.add((i, cc + dist_col))

    # Check all frame cells are 1
    for (r, c) in frame_cells:
        if grid[r][c] != 1:
            return False

    # Check isolation: no foreign 1s adjacent to frame
    for r, c in frame_cells:
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    # Check other cells at distance 1 (in any direction) 
                    # We need to check 8 neighbors
                    # Actually we should check: for neighbors of frame cells, they can't be 1 unless they ARE in the frame cell set
                    if (nr, nc) not in frame_cells and grid[nr][nc] == 1:
                        return False

    return True

