def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n1, n2, m = len(s1), len(s2), len(virus)

    if not virus:
        return s1  # No virus means any common subsequence is valid, but problem says 1 <= |virus|

    # Build KMP failure function
    failure = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and virus[k] != virus[i]:
            k = failure[k-1]
        if virus[k] == virus[i]:
            k += 1
        failure[i] = k

    # Build transition table: trans[state][char] -> next state
    # state goes from 0 to m-1 (we can't reach state m, that would mean virus substring found)
    trans = [[0] * 26 for _ in range(m)]
    for state in range(m):
        for c in range(26):
            char = chr(ord('A') + c)
            temp = state
            while temp > 0 and virus[temp] != char:
                temp = failure[temp-1]
            if virus[temp] == char:
                temp += 1
            trans[state][ord(char) - ord('A')] = min(temp, m - 1)  # Cap at m-1

    # dp[i][j][k] = maximum length of valid LCS using s1[0:i], s2[0:j], with virus match state k
    dp = {}

    # dp[(0,0,0)] = 0 represents empty strings with no virus match
    dp[(0, 0, 0)] = 0

    for i in range(n1 + 1):
        for j in range(n2 + 1):
            for k in range(m):
                if (i, j, k) not in dp:
                    continue

                current_len = dp[(i, j, k)]

                # Option 1: Skip s1[i] if i > 0
                if i > 0:
                    new_key = (i - 1, j, k)
                    if new_key not in dp or dp[new_key] < current_len:
                        dp[new_key] = current_len

                # Option 2: Skip s2[j] if j > 0
                if j > 0:
                    new_key = (i, j - 1, k)
                    if new_key not in dp or dp[new_key] < current_len:
                        dp[new_key] = current_len

                # Option 3: If characters match, try to extend
                if i > 0 and j > 0 and s1[i - 1] == s2[j - 1]:
                    char = s1[i - 1]
                    c_idx = ord(char) - ord('A')
                    new_state = trans[k][c_idx]

                    if new_state < m:  # Valid state (not completed virus)
                        new_key = (i, j, new_state)
                        if new_key not in dp or dp[new_key] < current_len + 1:
                            dp[new_key] = current_len + 1

    # Find the maximum length
    max_len = 0
    best_key = None
    for key, val in dp.items():
        i, j, k = key
        if val > max_len:
            max_len = val
            best_key = key

    if max_len == 0:
        return "0"

    # Reconstruct the solution by backtracking
    result = []
    i, j, k = n1, n2, 0

    while i > 0 and j > 0:
        # Check if we chose to match characters
        char = s1[i - 1] if i > 0 else ' '
        char = s2[j - 1] if j > 0 else ' '

        if s1[i - 1] == s2[j - 1]:
            if (i, j, k) in dp and dp[(i, j, k)] - dp[(i - 1, j - 1, k)] == 1:
                result.append(s1[i - 1])
                i -= 1
                j -= 1
            elif (i, j - 1, k) in dp:
                i -= 1
            j -= 1
        else:
            if (i - 1, j, k) in dp and dp[(i - 1, j, k)] == dp[(i, j, k)]:
                i -= 1
            else:
                j -= 1

    return ''.join(reversed(result))

