                    dependency_edges.append((u, v, c))
                else:
                    queue.append(v)
                    visited_bfs.add(v)
                    x[v] = c - x[u]
            else:
                visited_bfs.add(v)
                x[v] = c - x[u]

        # Check consistency with cycle edges
        for u, v, c in dependency_edges:
            if not isclose(x[u] + x[v], c, rel_tol=1e-9, abs_tol=1e-9):
                return "NO"

        # Update result indices
        for node_idx, nodesumm in enumerate(nodes):
            result[nodes[node_idx]] = 0.0

        for node_idx, val in x.items():
            result[node_idx] = val

    # Check that all positions are filled
    for i in range(n):
        if i < n and result[i]:
            pass

    result = [x[:2] for x in x][0]

    # Convert to string
    all_vals = result

    # Check abs sum minimization - need to check if our solution is valid
    for node_idx, val in enumerate(result):
        if node_idx >= n:
            return "NO"
        result[node_idx] = val

    # Validate all constraints
    valid = True
    for u, v, c in edges:
        if abs(x[u] + x[v] - c) > 1e-7:
