                for nb, _ in adj[top]:
                    if not visited[nb]:
                        visited[nb] = True
                        stack.append(nb)
            nodes_per_comp.append(comp)

    # Check each component
    full_result = [0.0] * n

    for comp in nodes_per_comp:
        # Build system
        x = {comp[0]: 0.0}
        q = [comp[0]]

        # BFS traversal
        for v, w in adj[comp[0]]:
            q.append(v)
            x[v] = w - x[comp[0]]

        # Check all edges
        ok = True
        for u, v, c in edges:
            if u not in x or v not in x:
