def solve_for_component(root, node, comp):
    # Linear system solving using reference to root
    x = {root: 0.0}
    equations = []

    def bfs(node):
        q = [node]
        visited = {node}
        while q:
            u = q.pop(0)
            for v, c in edges.fr:
                if v in x:
                    continue
                x[v] = c - x[u]
                equations.append((u, v, c))
                q.append(v)
                visited.add(v)

    equations = []
    x = {}
    q = [comp[0]]
    visited = {comp[0]}

    while q:
        u = q.pop(0)
        for v, c in adj[u]:
