    elif min_nm == 2:
        # If minimum dimension is 2:
        # - If both dimensions are 2, no pairs possible (max distance is 2)
        # - Otherwise, answer is 2*(max_nm - 1)
        if max_nm <= 2:
            return "0\n"
        else:
            return str(2 * (max_nm - 1)) + "\n"
    else:
        # If minimum dimension >= 3:
        # - If square board (n == m), answer is n*n - 1
        # - Otherwise, answer is 2*(min_nm - 1)*(max_nm - 1)
        if n == m:
            return str(n*n - 1) + "\n"
        else:
            return str(2 * (min_nm - 1) * (max_nm - 1)) + "\n"

from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    x, k, n, q = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    special = {}
    for line in lines[2:2+q]:
        p, w = map(int, line.split())
        special[p] = w

    # DP with state as sorted position tuples
    @lru_cache(maxsize=None)
    def dp(positions):
        if positions == tuple(range(n - x + 1, n + 1)):
            return 0

        positions_list = list(positions)
        leftmost = positions_list[0]

        ans = float('inf')

        for jump_len in range(1, k + 1):
            new_pos = leftmost + jump_len
            if new_pos >= positions_list[1]:
                continue

            cost = c[jump_len - 1]
            if new_pos in special:
                cost += special[new_pos]

            new_list = positions_list[:]
            new_list[0] = new_pos
            new_list.sort()

            ans = min(ans, cost + dp(tuple(new_list)))

        return ans

    return str(dp(tuple(range(1, x + 1)))) + '\n'

import re

MOD = 10**9 + 7

def value_and_len(s, pos):
    """Parse a regular number, return (value, length) and new position."""
    start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    s1 = int(s[start:pos])
    if s1 >= MOD:
        s1 = s1 % MOD
    l1 = pos - start
    return (s1 % MOD, l1, pos)

def parse_range(expr, pos):
    """Parse l-r, return (value, length) and new position."""
    l, _, pos = expr(pos)
    if pos == len(expr) and expr[pos].isdigit():
        r, _, pos = expr(pos)
        return solve_l_you(r, l, pos), pos

    return solve_l_you(""), l, pos

    def solve_l_you(r, l, pos):
        r = int(r)
        l = int(l)
        # For very large ranges, we need efficient concatenation
        # Concatenate numbers from l to r
        if l == r:
            return (l % MOD, len(str(l)), pos)

        result = ""
        for i in range(l, r + 1):
            result += str(i)

        val = int(result) % MOD
        l1 = len(result)
        return (val, l1, pos)

def parse_repetition(expr, pos):
    """Parse number(repetition), return (value, length) and new position."""
    num, _, pos = expr(pos)
    if pos < len(expr) and expr[pos] == '(':
        pos += 1
        val, l1, pos = expr(pos)
        if pos < len(expr) and expr[pos] == ')':
            pos += 1
            # Repeat val, l1, num times
            rep = num % MOD
            total_len = (l1 * num) % (MOD + 1)  # Actually we need exact length for concatenation
            total_len = l1 * num  # Python handles large integers

            if num == 0:
                return (0, 0, pos)

            total_val = 0
            mod_len = l1
            power = pow(10, mod_len, MOD)
            for i in range(num):
                total_val = (total_val * power + val) % MOD
            return (total_val, total_len, pos)

def parse_term(expr, pos):
    """Parse term: number | number - number | number (expression)"""
    num, _, pos = expr(pos)

    if pos < len(expr) and expr[pos].isdigit():
        r, _, pos = expr(pos)
        r = int(r)
        # l-r case
        return solve_l_you(r), pos
    elif pos < len(expr) and expr[pos] == '(':
        pos += 1
        val, l1, pos = expr(pos)
        if pos < len(expr) and expr[pos] == ')':
            pos += 1
            return solve_rep(num, val, l1), pos
    else:
        return num, pos

    def solve_l_you(r):
        l = int(r)
        # l-r case
        if l == r:
            v, l1, _ = value_and_len(r, int(r)-1)
            return v, l1
        # For large ranges, we need efficient computation
        result = ""
        for i in range(int(r), int(l)):
            result += str(i)
        return int(result) % MOD, len(result)

    def solve_rep(num, val, l1):
        rep = num % MOD
        return (val, l1, rep), num

