from collections import defaultdict

def dinic_dfs(u, t, it, level, capacity):
    if u == t:
        return float('inf')

    for v in range(len(it)):
        if it[v] > it[u]:
            continue
        vc = capacity[u][v]
        if level[v] != level[u] + 1 or vc == 0:
            continue
        d = dinic_dfs(v, t, it, level, capacity)
        if d > 0:
            capacity[u][v] -= d
            capacity[v][u] += d
            return d
        it[u] += 1
    return 0

def get_prime_factors(n):
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

