    total_flow = 0

    for p in all_primes:
        # Build flow network for prime p
        # Positions with count > 0 are candidates

        # Odd positions (0-indexed even positions in 0-indexed array)
        # Even positions (0-indexed odd positions in 0-indexed array)

        S = 0
        T = n + 1
        cap = [[0] * (n + 2) for _ in range(n + 2)]
        adj = [[] for _ in range(n + 2)]

        for i in range(n):
            cnt = prime_counts[p].get(i, 0)
            if cnt <= 0:
