            if i % 2 == 0:  # Odd index in original (0-indexed even)
                cap[S][i + 1] = cnt
                adj[S].append(i + 1)
            else:  # Even index in original (0-indexed odd)
                cap[i + 1][T] = cnt
                adj[i + 1].append(T)

        # Add edges for good pairs
        for u, v in good_pairs:
            # Original pair: u < v, u + v is odd
            cnt_u = prime_counts[p].get(u, 0)
            cnt_v = prime_counts[p].get(v, 0)
            if cnt_u > 0 and cnt_v > 0:
                cap[u + 1][v + 1] = min(cnt_u, cnt_v)
                cap[v + 1][u + 1] = min(cnt_u, cnt_v)
                if v + 1 not in adj[u + 1]:
                    adj[u + 1].append(v + 1)
                if u + 1 not in adj[v + 1]:
                    adj[v + 1].append(u + 1)

        # Dinic's algorithm
        flow = 0
        while True:
            level = [-1] * (n + 2)
            level[S] = 0
            queue = [S]
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if cap[u][v] > 0 and level[v] == -1:
                        level[v] = level[u] + 1
                        queue.append(v)

            if level[T] == -1:
