    for u, v in roads:
        add_edge(u, v, INF)
        add_edge(v, u, INF)

    # Self-loops for staying in the same city
    for i in range(1, n + 1):
        add_edge(i, i, INF)

    # Max flow with BFS (Edmonds-Karp)
    def bfs():
        level = [-1] * num_nodes
        level[source] = 0
        queue = deque([source])
