import math

def rev(n):
    """Reverse the number n, leading zeros disappear."""
    return int(str(n)[::-1])

def is_lucky(a, b):
    """Check if (a, b) is a lucky ticket."""
    return a * b == rev(a) * rev(b)

def count_lucky_tickets(maxx, maxy, w):
    """
    Count lucky tickets in range [1, maxx] × [1, maxy].
    Returns the count.
    """
    # Precompute lucky check results for efficiency
    lucky = [[False] * (maxy + 1) for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            lucky[a][b] = is_lucky(a, b)

    # Count total lucky tickets
    count = 0
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if lucky[a][b]:
                count += 1
    return count

def get_lucky_count(num_a, num_b, maxx, maxy):
    """
    Use Lucas theorem or simple division to partition the grid
    and count lucky tickets using prefix-like sums.

    This is complex, so let's use a simpler but less efficient approach
    that works given constraints.
    """
    lucky = [[False] * (maxy + 1) for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            lucky[a][b] = is_lucky(a, b)

    # 2D prefix sum array
    prefix = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            prefix[a][b] = prefix[a-1][b] + prefix[a][b-1] - prefix[a-1][b-1] + lucky[a][b]

    def query(x, y):
        if x > maxx or y > maxy:
