            elif j == 0:
                # Second beacon at origin
                # Check if first beacon position (i, 0) allows valid third position
                if i > 0 and (2 * s) % i == 0:
                    count += 1
            else:
                # Both off origin
                # Check gcd(i, j) | 2s
                if (2 * s) % gcd(i, j) == 0:
                    count += 1
    return count

