def solution(s):
    lines = s.strip().split('\n')

    if not lines:
        return "-1"

    n, m = map(int, lines[0].split())

    A = []
    for i in range(n):
        A.append(list(map(int, lines[1 + i].split())))

    B = []
    for i in range(n):
        B.append(list(map(int, lines[1 + n + i].split())))

    # Flatten and check multiset equality
    A_flat = sum(A, [])
    B_flat = sum(B, [])
    if sorted(A_flat) != sorted(B_flat):
        return "-1"

    # Check if already equal (0 sortings)
    if all(A[i][j] == B[i][j] for i in range(n) for j in range(m)):
        return "0"

    # Helper to check equality
    def tables_equal(t1, t2):
        return all(t1[i][j] == t2[i][j] for i in range(n) for j in range(m))

    # Try DFS approach
    # Start from A and try different column sorting sequences
    visited = set()

    def dfs(current_state, path):
        # State is the current table configuration (as a tuple of tuples for hashability)
        if tables_equal(current_state, B):
            return path[:]

        state_key = tuple(tuple(row) for row in current_state)
        if state_key in visited:
            return None

        visited.add(state_key)

        if len(path) >= 5000:
            return None

        # Try each column
        for col in range(m):
            new_state = [current_state[i][:] for i in range(n)]

            # Sort by this column (stable sort)
            indices = sorted(range(n), key=lambda i: current_state[i][col])
            new_state = [current_state[i] for i in indices]

            res = dfs(tuple(tuple(row) for row in new_state), path + [col + 1])
            if res:
                return res

        return None

    initial_state = tuple(tuple(row) for row in A)
    result = dfs(initial_state, [])

    if result:
        return f"{len(result)}\n{' '.join(map(str, result))}"
    else:
        return "-1"

