from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m, k = map(int, lines[0].split())

    adj = defaultdict(list)
    for i in range(m):
        u, v, x = map(int, lines[1 + i].split())
        adj[u].append((v, x))
        adj[v].append((u, x))

    trains = []
    for i in range(k):
        s, y = map(int, lines[1 + m + i].split())
        trains.append((s, y))

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[1] = 0

    pq = [(0, 1)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, x in adj[u]:
            if dist[u] + x < dist[v]:
                dist[v] = dist[u] + x
                heapq.heappush(pq, (dist[v], v))

    train_counts = defaultdict(int)
    for s, y in trains:
        train_counts[y] += 1

    keep_needed = 0
    for s, y in trains:
        if dist[s] == INF:
            continue
        if y > dist[s]:
            continue

        if train_counts[y] > 1:
            keep_needed += 1
        else:
            if dist[s] == INF:
                keep_needed += 1
            elif y == dist[s]:
                # Need a road path to use this train, so train is needed
                keep_needed += 1

    answer = k - keep_needed
    return f"{answer}\n"


