MOD = 10**9 + 7

def get_square_free_part(n):
    """Get the square-free part of n by dividing out all square factors."""
    result = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            count = 0
            while n % d == 0:
                count += 1
                n //= d
            if count % 2 == 1:
                result *= d
        d += 1
    if n > 1:
        result *= n
    return result

