    # dp[i][j] = number of valid arrangements using first i groups with j "available gaps"

    # Standard solution approach:
    # For each group, place its elements in different "gaps"
    # A "gap" is a position where we can place an element without creating adjacent conflicts
    #
    # After processing k groups with sizes s[0], s[1], ..., s[k-1]:
    # - Total elements placed = sum(s[0..k-1])
    # - Available gaps = sum(s[0..k-1]) + 1
    #
    # For the current group with size s[k], we need to place s[k] elements
    # into the available gaps such that no two from the same group are adjacent
    #
    # The number of ways to do this is: C(gaps - 1, group_size - 1) * (gaps)! / (gaps - (group_size - 1))!
    # 
    # Actually simpler: we have (current + 1) gaps, need to choose group_size distinct gaps
    # Ways = C(current + 1, group_size) * (current + 1)! / i! where i is permutations

    current = 0  # number of elements already placed
    prev = 1
