        gaps = current + 1

        if siz > gaps:
            # Cannot place this group without adjacency (should limit logic height)
            prev = 0
            break

        # Ways to choose 'siz' gaps from 'gaps' available positions: C(gaps, siz)
        comb = combinations(gaps, siz)

        # The number of tuples (gaps, group_size) = C(gaps - 1, siz - 1) * siz!
        # places each element in one of selected gaps

        new_perm_mod = (prev * comb) % MOD

        # Update current
        current += siz
        prev = new_perm_mod

    result = (prev * combinations(current, n)) % MOD

