def count_small(n):
    """Helper to compute for small n using DP approach"""
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, current_sum):
        """Count distinct sums achievable with exactly i coins"""
        if i == 0:
            return 1 if current_sum == 0 else 0

        count = 0
        for coin in [1, 5, 10, 50]:
            if current_sum + coin <= 50 * n:
                count += dp(i-1, current_sum + coin)
        return count

    return dp(n, 0)


