        return "0\n"

    def build_modified_adj(c, present):
        """Simulate tree after removing candidate vertex c"""
        modified_adj = defaultdict(list)

        # Parent and children in original complete binary tree
        c_parent = c // 2 if c != 1 else -1
        c_children = [2*c, 2*c + 1]

        # Build adjacency without c, with parent's children connections
        for v in present:
            if v == c:
                continue
            for neighbor in adj[v]:
                if neighbor != c:
                    modified_adj[v].append(neighbor)

        # Connect parent to c's children (if they exist and are still in present)
        if c_parent != -1 and c_parent in present:
            for child in c_children:
                if child in present and child != c:
                    modified_adj[c_parent].append(child)
                    modified_adj[child].append(c_parent)

        return modified_adj

