        """Compute a canonical signature for tree structure"""
        # Get vertices and degrees
        vertices = list(adj.keys())
        degrees = {v: len(adj[v]) for v in vertices}

        # Sort by degree and then by smallest neighbor (canonical ordering)
        if not vertices:
            return ()

        # Root should be degree-1 or minimum degree node for n-leaf tree
        # Sort vertices canonically
        root = min(vertices)

        def dfs(u, parent):
            children = [v for v in adj[u] if v != parent]
            children.sort()
            child_sigs = tuple(dfs(child, u) for child in children)
            return (u, tuple(sorted(child_sigs)))

        root_sig = dfs(root, -1)
        return root_sig

    def is_isomorphic(adj1, adj2):
        """Check if two trees are isomorphic via isomorphism check"""
        if len(adj1) != len(adj2):
            return False

        # Build canonical form using DFS from same root
        def build_signature(u, parent):
            children = sorted([v for v in adj[u] if v != parent])
            child_sigs = tuple(sorted(build_signature(child, u) for child in children))
            return child_sigs

        # Need to check if the trees structure is identical
        # Use degree sequences as a first filter
        deg1 = Counter(len(adj1[v]) for v in adj1)
        deg2 = Counter(len(adj2[v]) for v in adj2)
        if deg1 != deg2:
