def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for r in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            matrix.append(row)

        ops = lines[idx]
        idx += 1

        for op in ops:
            if op == 'R':
                # Cyclically shift columns right: element at j comes from (j-1) mod n
                new_matrix = []
                for r in range(n):
                    new_row = [matrix[r][(j - 1) % n] for j in range(n)]
                    new_matrix.append(new_row)
                matrix = new_matrix
            elif op == 'L':
                # Cyclically shift columns left: element at j comes from (j+1) mod n
                new_matrix = []
                for r in range(n):
                    new_row = [matrix[r][(j + 1) % n] for j in range(n)]
                    new_matrix.append(new_row)
                matrix = new_matrix
            elif op == 'D':
                # Cyclically shift rows down: row at i comes from (i-1) mod n
                new_matrix = [matrix[(i - 1) % n] for i in range(n)]
                matrix = new_matrix
            elif op == 'U':
                # Cyclically shift rows up: row at i comes from (i+1) mod n
                new_matrix = [matrix[(i + 1) % n] for i in range(n)]
                matrix = new_matrix
            elif op == 'I':
                # Invert permutation in each row
                for r in range(n):
                    new_row = [0] * n
                    for c in range(n):
                        new_row[matrix[r][c]] = c + 1
                    matrix[r] = new_row
            elif op == 'C':
                # Invert permutation in each column
                new_matrix = [[0] * n for _ in range(n)]
                for c in range(n):
                    inv = [0] * (n + 1)
                    for r in range(n):
                        inv[matrix[r][c]] = r + 1
                    for c_idx in range(n):
                        new_matrix[r][c_idx] = inv[r + 1] if r < n else inv[r + 1]
                matrix = new_matrix

        results.append('\n'.join(' '.join(map(str, row)) for row in matrix))

    return '\n'.join(results)

