    receives = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if adj[i][j] == 1:
                receives[j].append(i)

    def backtrack(idx, counts, selected):
        # Check if current counts are valid
        for i in range(n):
            if counts[i] == preds[i]:
                return None

        # Base case: all people processed
        if idx == n:
            if all(counts[i] != preds[i] for i in range(n)):
                return selected[:]
            return None

        # Try without person idx
        res = backtrack(idx + 1, counts, selected)
        if res is not None:
            return res

        # Try with person idx
        new_counts = counts[:]
        for k in receives[idx]:
            new_counts[k] += 1

        # Quick check: if any count already matches, continue but be prepared to backtrack
        if all(new_counts[i] != preds[i] for i in range(n)):
            selected.append(idx)
            res = backtrack(idx + 1, new_counts, selected)
            if res is not None:
                return res
            selected.pop()

        return None

    result = backtrack(0, [0] * n, [])

    if result:
        one_indexed = [i + 1 for i in result]
        return f"{len(one_indexed)}\n{' '.join(map(str, one_indexed))}"

    # Empty set solution
    if all(p != 0 for p in preds):
        return "0\n"

    return "-1\n"

