import math

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n+1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    def check(X):
        total_hits_needed = 0
        for h, a in bamboos:
            final_height_without_hits = h + m * a
            if final_height_without_hits > X:
                hits_needed = (final_height_without_hits - X + p - 1) // p
                total_hits_needed += hits_needed
        return total_hits_needed <= k * m

    # Binary search for the answer
    low = 0
    high = max(h + m*a for h, a in bamboos) + p * m * n  # upper bound
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(ans)

