    def count_decompositions(n, fibs):
        """
        Count decompositions of n into sum of distinct Fibonacci numbers
        Uses a greedy approach with backtracking
        """
        memo = {}

        def dp(idx, remaining):
            if remaining == 0:
                return 1
            if remaining < 0 or idx >= len(fibs):
                return 0

            state = (idx, remaining)
            if state in memo:
                return memo[state]

            # Option 1: Don't include fibs[idx]
            count = dp(idx + 1, remaining)

            # Option 2: Include fibs[idx] if possible
            if remaining >= fibs[idx]:
                count += dp(idx + 1, remaining - fibs[idx])

            memo[state] = count
            return count

        return dp(0, n)

    results = []
    for n in test_cases:
        results.append(str(count_decompositions(n, fibs)))

    return '\n'.join(results)

